sys_script.script:
(function(current) {
    // Only process our specific catalog item
    var catItemGR = new GlideRecord('sc_cat_item');
    catItemGR.addQuery('name', 'Continuity Absence Request');
    catItemGR.addQuery('sys_scope', '35f8e15683a85310e1615529feaad35a');
    catItemGR.query();
    if (!catItemGR.next()) return;

    if (current.getValue('cat_item') != catItemGR.getUniqueValue()) return;

    // Get the approving_manager variable value
    var approvingManager = current.variables.approving_manager.toString();
    if (!approvingManager) return;

    // Set RITM to waiting for approval
    current.setValue('approval', 'requested');
    current.setWorkflow(false);
    current.update();

    // Create the sysapproval_approver record
    var approver = new GlideRecord('sysapproval_approver');
    approver.initialize();
    approver.setValue('approver', approvingManager);
    approver.setValue('sysapproval', current.getUniqueValue());
    approver.setValue('source_table', 'sc_req_item');
    approver.setValue('state', 'requested');
    approver.insert();
})(current);
